 'sha256': lambda b: hashlib.sha256(b).hexdigest(),
 'sha3_256': lambda b: hashlib.sha3_256(b).hexdigest(),
 'blake2b32': lambda b: hashlib.blake2b(b, digest_size=32).hexdigest(),
 'blake2s': lambda b: hashlib.blake2s(b).hexdigest(),
 'sha512_256': lambda b: hashlib.sha512(b).digest()[:32].hex(),
 'blake2b64': lambda b: hashlib.blake2b(b).hexdigest(),
}
targets = {
 ( "", "") : "0da93df81dd23c470ba84c7b241e1674d7e7f065fcfbc3dc3d42ee017cd81f0c",
 ("x","") : "483b9a460587257b73e0b50c3784c21c17629ed4596727430b87fdbb48757ab0",
 ("","y") : "c6e648bd476f1d2e6fd68abb2fdf7802292bd55d64e99e7635ea41e77c8c8b6c",
}
def cands(q,a):
    out={}
    for pre in ["", "Q:", "Q: ", "Q:\n"]:
        for sep in ["", "\n", "\nA:", "\nA: ", "\n\nA: ", "\nA: \n"]:
            for suf in ["", "\n", "\n\n"]:
                s = pre+q+sep+a+suf
                out[s]=1
    out[q+a]=1
