import json, os, shutil, subprocess, sqlite3, sys, time, urllib.request, urllib.error, re, signal, random

EXE='/workspace/executable'

def free_port():
    import socket
    s=socket.socket(); s.bind(('127.0.0.1',0)); p=s.getsockname()[1]; s.close(); return p

def setup_dir(path, cards):
    """cards: list of (q,a)"""
    shutil.rmtree(path, ignore_errors=True)
    os.makedirs(path)
    names=[]
    for i,(q,a) in enumerate(cards):
        fn=os.path.join(path,'f%03d.md'%i)
        with open(fn,'w') as f:
            f.write('Q: '+q.replace('\n','\n')+'\nA: '+a+'\n')
        names.append(fn)
    return names

