def card_hash(path):
    out=subprocess.run([EXE,'export',path],capture_output=True,text=True).stdout
    data=json.loads(out)
    return {c['hash']: c for c in data['cards']}

def start_drill(path, port, extra=None):
    cmd=[EXE,'drill','--open-browser','false','--port',str(port),'--host','127.0.0.1']
    if extra: cmd+=extra
    cmd.append(path)
