import sys; sys.path.insert(0,'/tmp')
from nm import nelder_mead
import json, math, random
F=19.0/81.0
def negR(T,S): return 1.0-(1.0+F*T/S)**(-0.5)
data=[]
df=json.load(open('/tmp/data2_Forgot.json'))
for r in df:
    if abs(r['Sp']-r['S'])<1e-12: continue
    data.append((r['S'],r['D'],r['T'],r['Sp']))
def model(p,S,D,T):
    w11,w12,w13,w14=p
    return w11*(D**(-w12))*(((S+1.0)**w13)-1.0)*math.exp(w14*negR(T,S))
def obj(p):
    if p[0]<=0: return 1e18
    s=0.0
    for S,D,T,Sp in data:
        pr=model(p,S,D,T)
        if pr<=0: return 1e18
        s+=(math.log(pr)-math.log(Sp))**2
    return s
best=None
random.seed(1)
for trial in range(80):
    x0=[random.uniform(0.01,10),random.uniform(0.01,2),random.uniform(0.1,3),random.uniform(0.1,5)]
    x,v=nelder_mead(obj,x0,0.5,6000)
    if best is None or v<best[1]: best=(list(x),v)
print('best',best[0],best[1])
p=best[0]
me=0; worst=None
for S,D,T,Sp in data:
    pr=model(p,S,D,T)
    rel=abs(pr-Sp)/Sp
    if rel>me: me=rel; worst=(S,D,T,pr,Sp)
print('max rel err %.3e'%me, worst)
