import math
W=[0.40255,1.18385,3.173,15.69105,7.1949,0.5345,1.4604,0.0046,1.54575,0.1192,1.01925,1.9395,0.11,0.29605,2.2698,0.2315,2.9898]
FACTOR=19.0/81.0
DECAY=-0.5
def init_d(g): return W[4]-math.exp(W[5]*(g-1))+1
def next_d(D,g):
    delta=W[6]*(3.0-g)*(10.0-D)/9.0
    nd=D+delta
    return (1.0-W[7])*nd+W[7]*init_d(4)
def clamp(v,lo,hi): return max(lo,min(hi,v))
def next_s(S,D,T,g):
    R=(1.0+FACTOR*T/S)**DECAY
    if g==1:
        f=W[11]*(D**(-W[12]))*(((S+1.0)**W[13])-1.0)*math.exp(W[14]*(1.0-R))
        return min(f,S)
    a=math.exp(W[8])*(11.0-D)*S**(-W[9])
    b=math.exp(W[10]*(1.0-R))-1.0
    hp=W[15] if g==2 else 1.0
    eb=W[16] if g==4 else 1.0
    return S*(1.0+a*b*hp*eb)
def interval_raw(S):
    return S/FACTOR*(0.9**(1.0/DECAY)-1.0)
