GMAP={'Hard':2,'Good':3,'Easy':4}
pts=[]
for g in ['Hard','Good','Easy']:
    for fn in ['data','data2']:
        try: d=json.load(open('/tmp/%s_%s.json'%(fn,g)))
        except: continue
        for r in d: pts.append((r['S'],r['D'],r['T'],GMAP[g],r['Sp']))
def nr(T,S): return 1.0-(1.0+F*T/S)**DEC
def av(S,D): return E8*(11.0-D)*S**(-W9)
def bv(T,S): return math.exp(W10*nr(T,S))-1.0
growths={
 'g1': lambda a,b,hp,eb: ((a*b)*hp)*eb,
 'g2': lambda a,b,hp,eb: (a*(b*hp))*eb,
 'g3': lambda a,b,hp,eb: a*(b*(hp*eb)),
 'g4': lambda a,b,hp,eb: a*((b*hp)*eb),
 'g5': lambda a,b,hp,eb: (a*hp)*(b*eb),
 'g6': lambda a,b,hp,eb: a*b*hp*eb,
 'g7': lambda a,b,hp,eb: (a*b)*(hp*eb),
}
finals={
 'f1': lambda S,g: S*(1.0+g),
 'f2': lambda S,g: S+S*g,
 'f3': lambda S,g: g*S+S,
 'f4': lambda S,g: S*(1.0+g),
}
best=None
for gk,gv in growths.items():
    for fk,fv in finals.items():
        bad=0; worst=None
        for S,D,T,G,obs in pts:
