            hp=W15 if G==2 else 1.0
            eb=W16 if G==4 else 1.0
            g=gv(a,b,hp,eb)
            pr=fv(S,g)
            if pr!=obs:
                bad+=1
                if worst is None or abs(pr-obs)>worst[0]: worst=(abs(pr-obs),S,D,T,G,pr,obs)
        if best is None or bad<best[0]: best=(bad,gk,fk,worst)
        if bad==0: print('EXACT',gk,fk)
print('best',best)
