 'r3': lambda T,S: math.pow(1.0+F*T/S,DEC),
 'r4': lambda T,S: (1.0+T*F/S)**DEC,
}
def mk_a(v):
    if v==0: return lambda S,D: E8*(11.0-D)*S**(-W9)
    if v==1: return lambda S,D: E8*(11.0-D)*(1.0/S**W9)
    if v==2: return lambda S,D: E8*(11.0-D)*math.pow(S,-W9)
    if v==3: return lambda S,D: (E8*(11.0-D))*S**(-W9)
    if v==4: return lambda S,D: E8*((11.0-D)*S**(-W9))
    if v==5: return lambda S,D: math.exp(W8)*(11.0-D)*S**(-W9)
