    if v==1: return lambda T,S,R: math.expm1(W10*(1.0-R))
    if v==2: return lambda T,S,R: math.exp((1.0-R)*W10)-1.0
    if v==3: return lambda T,S,R: math.exp(W10-W10*R)-1.0
