 'x1': lambda S,g: S*(1.0+g),
 'x2': lambda S,g: S+S*g,
}
best=None
for rk,rf in Rv.items():
  for ai in range(6):
    A=mk_a(ai)
    for bi in range(5):
      B=mk_b(bi)
      for fk,fv in finals.items():
