import math
W=[0.40255,1.18385,3.173,15.69105,7.1949,0.5345,1.4604,0.0046,1.54575,0.1192,1.01925,1.9395,0.11,0.29605,2.2698,0.2315,2.9898]
FACTOR=19.0/81.0
DECAY=-0.5
MAX_INTERVAL=256.0
def init_d(g): return W[4]-math.exp(W[5]*(g-1))+1.0
def clamp_d(v): return max(1.0,min(10.0,v))
def next_d(D,g):
    delta=W[6]*(3.0-g)*(10.0-D)/9.0
    nd=D+delta
    return clamp_d((1.0-W[7])*nd+W[7]*init_d(4))
def retrievability(T,S): return (1.0+FACTOR*(T/S))**DECAY
def next_s(S,D,T,g):
    R=retrievability(T,S)
    if g==1:
        f=(D**(-W[12]))*(((S+1.0)**W[13])-1.0)*(math.exp(W[14]*(1.0-R)))*W[11]
        return min(f,S)
    X=W[15] if g==2 else (W[16] if g==4 else 1.0)
    a=(11.0-D)*S**(-W[9])
    b=math.exp(W[10]*(1.0-R))-1.0
    return S*(1.0+(((a*b)*X)*math.exp(W[8])))
def interval_raw(S): return min(MAX_INTERVAL, S/FACTOR*(0.9**(1.0/DECAY)-1.0))
def rust_round(x): return math.floor(x+0.5) if x>=0 else math.ceil(x-0.5)
def interval_days(S): return int(max(1.0, rust_round(interval_raw(S))))
