use clap::{Command, Arg, ArgAction, ValueEnum};

#[derive(Clone, Copy, PartialEq, Eq)]
enum AnswerControls { Full, Binary }
impl clap::ValueEnum for AnswerControls {
    fn value_variants<'a>() -> Vec<clap::builder::PossibleValue> {
        vec![
            clap::builder::PossibleValue::new("full").help("Show all four rating buttons (Forgot/Hard/Good/Easy)"),
            clap::builder::PossibleValue::new("binary").help("Show only two rating buttons (Forgot/Good)"),
        ]
    }
    fn to_possible_value(&self) -> Option<clap::builder::PossibleValue> {
        Some(match self { AnswerControls::Full => clap::builder::PossibleValue::new("full"), AnswerControls::Binary => clap::builder::PossibleValue::new("binary") })
    }
}
impl std::str::FromStr for AnswerControls {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, String> { Ok(match s { "full" => AnswerControls::Full, "binary" => AnswerControls::Binary, _ => return Err(s.to_string()) }) }
}

fn main() {
    let drill = Command::new("drill")
        .about("Drill cards through a web interface")
        .arg(Arg::new("directory").value_name("DIRECTORY").required(false).help("Path to the collection directory. By default, the current working directory is used"))
        .arg(Arg::new("card-limit").long("card-limit").value_name("CARD_LIMIT").help("Maximum number of cards to drill in a session. By default, all cards due today are drilled"))
        .arg(Arg::new("host").long("host").value_name("HOST").default_value("127.0.0.1").help("The host address to bind to. Default is 127.0.0.1"))
        .arg(Arg::new("answer-controls").long("answer-controls").value_name("ANSWER_CONTROLS").default_value("full").value_parser(clap::builder::PossibleValuesParser::new(["full","binary"])).help("Which answer controls to show:"))
        ;
    let cmd = Command::new("hashcards")
        .about("A plain text-based spaced repetition system.")
        .subcommand(drill)
        .subcommand_required(true)
        .arg_required_else_help(true);
    let matches = cmd.get_matches();
    println!("{:?}", matches);
}
