{"command": "cat > src/fsrs.rs <<'RSEOF'
// FSRS-5 style spaced repetition scheduler.
//
// The parameters below are the ones the tool was trained/evaluated with; they
// were recovered by observing the behaviour of the reference implementation.

pub const W: [f64; 17] = [
    0.40255,  // 0 initial stability, rating forgot
    1.18385,  // 1 initial stability, rating hard
    3.173,    // 2 initial stability, rating good
    15.69105, // 3 initial stability, rating easy
    7.1949,   // 4 initial difficulty base
    0.5345,   // 5 initial difficulty decay
    1.4604,   // 6 difficulty delta
    0.0046,   // 7 difficulty mean reversion
    1.54575,  // 8 stability growth
    0.1192,   // 9 stability exponent
    1.01925,  // 10 retrievability exponent
    1.9395,   // 11 post lapse coefficient
    0.11,     // 12 post lapse difficulty exponent
    0.29605,  // 13 post lapse stability exponent
    2.2698,   // 14 post lapse retrievability exponent
    0.2315,   // 15 hard penalty
    2.9898,   // 16 easy bonus
];

pub const FACTOR: f64 = 19.0 / 81.0;
pub const DECAY: f64 = -0.5;
pub const MAX_INTERVAL: i64 = 256;
pub const DESIRED_RETENTION: f64 = 0.9;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Grade {
    Forgot = 1,
    Hard = 2,
    Good = 3,
    Easy = 4,
}

impl Grade {
    pub fn value(self) -> f64 {
        match self {
            Grade::Forgot => 1.0,
            Grade::Hard => 2.0,
            Grade::Good => 3.0,
            Grade::Easy => 4.0,
        }
    }
    pub fn from_str(s: &str) -> Option<Grade> {
        match s {
            "forgot" => Some(Grade::Forgot),
            "hard" => Some(Grade::Hard),
            "good" => Some(Grade::Good),
            "easy" => Some(Grade::Easy),
            _ => None,
        }
    }
    pub fn as_str(self) -> &'static str {
        match self {
            Grade::Forgot => "forgot",
            Grade::Hard => "hard",
            Grade::Good => "good",
            Grade::Easy => "easy",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MemoryState {
    pub stability: f64,
    pub difficulty: f64,
}

impl MemoryState {
    pub fn new(grade: Grade) -> MemoryState {
        MemoryState {
            stability: W[grade.value() as usize - 1],
            difficulty: init_difficulty(grade),
        }
    }
}

pub fn init_difficulty(grade: Grade) -> f64 {
    W[4] - (W[5] * (grade.value() - 1.0)).exp() + 1.0
}

pub fn clamp_difficulty(d: f64) -> f64 {
    if d < 1.0 {
        1.0
    } else if d > 10.0 {
        10.0
    } else {
        d
    }
}

pub fn next_difficulty(difficulty: f64, grade: Grade) -> f64 {
    let delta = W[6] * (3.0 - grade.value()) * (10.0 - difficulty) / 9.0;
    let next = difficulty + delta;
    let reverted = (1.0 - W[7]) * next + W[7] * init_difficulty(Grade::Easy);
    clamp_difficulty(reverted)
}

pub fn retrievability(elapsed_days: f64, stability: f64) -> f64 {
    (1.0 + FACTOR * (elapsed_days / stability)).powf(DECAY)
}

pub fn next_stability(stability: f64, difficulty: f64, elapsed_days: f64, grade: Grade) -> f64 {
    let r = retrievability(elapsed_days, stability);
    if grade == Grade::Forgot {
        let a = difficulty.powf(-W[12]);
        let b = (stability + 1.0).powf(W[13]) - 1.0;
        let c = (W[14] * (1.0 - r)).exp();
        let v = a * b * c * W[11];
        if v < stability {
            v
        } else {
            stability
        }
    } else {
        let a = (11.0 - difficulty) * stability.powf(-W[9]);
        let b = (W[10] * (1.0 - r)).exp() - 1.0;
        let x = if grade == Grade::Hard {
            W[15]
        } else if grade == Grade::Easy {
            W[16]
        } else {
            1.0
        };
        stability * (1.0 + ((a * b) * x) * W[8].exp())
    }
}

pub fn interval_raw(stability: f64) -> f64 {
    stability / FACTOR * (DESIRED_RETENTION.powf(1.0 / DECAY) - 1.0)
}

pub fn round_half_away(x: f64) -> f64 {
    (x + 0.5).floor()
}

pub fn interval_days(stability: f64) -> i64 {
    let raw = interval_raw(stability);
    let mut days = round_half_away(raw) as i64;
    if days < 1 {
        days = 1;
    }
    if days > MAX_INTERVAL {
        days = MAX_INTERVAL;
    }
    days
}

#[derive(Debug, Clone, Copy)]
pub struct Scheduled {
    pub state: MemoryState,
    pub interval_raw: f64,
    pub interval_days: i64,
}

pub fn review(state: Option<MemoryState>, elapsed_days: i64, grade: Grade) -> Scheduled {
    let state = match state {
        None => MemoryState::new(grade),
        Some(s) => {
            let difficulty = next_difficulty(s.difficulty, grade);
            let stability = next_stability(s.stability, s.difficulty, elapsed_days as f64, grade);
            MemoryState { stability, difficulty }
        }
    };
    let interval_raw = interval_raw(state.stability);
    let interval_days = interval_days(state.stability);
    Scheduled { state, interval_raw, interval_days }
}
RSEOF
echo ok"}

