pub struct MemoryState {
    pub stability: f64,
    pub difficulty: f64,
}

impl MemoryState {
    pub fn new(grade: Grade) -> MemoryState {
        MemoryState {
            stability: W[grade.value() as usize - 1],
            difficulty: init_difficulty(grade),
        }
    }
}

pub fn init_difficulty(grade: Grade) -> f64 {
    W[4] - (W[5] * (grade.value() - 1.0)).exp() + 1.0
}

pub fn clamp_difficulty(d: f64) -> f64 {
    if d < 1.0 {
        1.0
    } else if d > 10.0 {
        10.0
    } else {
        d
    }
}

pub fn next_difficulty(difficulty: f64, grade: Grade) -> f64 {
    let delta = W[6] * (3.0 - grade.value()) * (10.0 - difficulty) / 9.0;
    let next = difficulty + delta;
    let reverted = (1.0 - W[7]) * next + W[7] * init_difficulty(Grade::Easy);
    clamp_difficulty(reverted)
}

pub fn retrievability(elapsed_days: f64, stability: f64) -> f64 {
    (1.0 + FACTOR * (elapsed_days / stability)).powf(DECAY)
}

pub fn next_stability(stability: f64, difficulty: f64, elapsed_days: f64, grade: Grade) -> f64 {
    let r = retrievability(elapsed_days, stability);
    if grade == Grade::Forgot {
