    }
}

pub fn interval_raw(stability: f64) -> f64 {
    stability / FACTOR * (DESIRED_RETENTION.powf(1.0 / DECAY) - 1.0)
}

pub fn round_half_away(x: f64) -> f64 {
    (x + 0.5).floor()
}

pub fn interval_days(stability: f64) -> i64 {
    let raw = interval_raw(stability);
    let mut days = round_half_away(raw) as i64;
    if days < 1 {
        days = 1;
    }
    if days > MAX_INTERVAL {
        days = MAX_INTERVAL;
    }
    days
}

