    fn sqlite3_libversion() -> *const c_char;
}

const SQLITE_OK: c_int = 0;
const SQLITE_ROW: c_int = 100;
const SQLITE_DONE: c_int = 101;
const SQLITE_OPEN_READWRITE: c_int = 2;
const SQLITE_OPEN_CREATE: c_int = 4;

pub struct Conn {
    handle: *mut c_void,
}

pub enum Value {
    Null,
    Text(String),
    Real(f64),
    Int(i64),
}

pub struct Row {
    pub values: Vec<Value>,
}

impl Row {
    pub fn text(&self, i: usize) -> Option<String> {
        match &self.values[i] {
            Value::Null => None,
            Value::Text(s) => Some(s.clone()),
            Value::Int(v) => Some(v.to_string()),
            Value::Real(v) => Some(v.to_string()),
        }
    }
    pub fn real(&self, i: usize) -> Option<f64> {
        match &self.values[i] {
            Value::Null => None,
            Value::Text(s) => s.parse().ok(),
            Value::Int(v) => Some(*v as f64),
            Value::Real(v) => Some(*v),
        }
    }
    pub fn int(&self, i: usize) -> Option<i64> {
        match &self.values[i] {
            Value::Null => None,
            Value::Text(s) => s.parse().ok(),
            Value::Int(v) => Some(*v),
            Value::Real(v) => Some(*v as i64),
        }
    }
}

fn last_error(db: *mut c_void) -> String {
    unsafe {
        let p = sqlite3_errmsg(db);
        if p.is_null() {
            "unknown sqlite error".to_string()
        } else {
            CStr::from_ptr(p).to_string_lossy().into_owned()
        }
    }
}

impl Conn {
    pub fn open(path: &str) -> Result<Conn, String> {
        let cpath = CString::new(path).map_err(|_| "invalid path")?;
        let mut handle: *mut c_void = std::ptr::null_mut();
        unsafe {
            let rc = sqlite3_open_v2(
                cpath.as_ptr(),
                &mut handle,
                SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE,
                std::ptr::null(),
            );
            if rc != SQLITE_OK {
                let msg = if handle.is_null() {
                    format!("unable to open database file: {}", path)
                } else {
                    last_error(handle)
                };
                if !handle.is_null() {
                    sqlite3_close_v2(handle);
                }
                return Err(msg);
            }
        }
        Ok(Conn { handle })
    }

    pub fn exec(&self, sql: &str) -> Result<(), String> {
        let csql = CString::new(sql).map_err(|_| "invalid sql")?;
        unsafe {
            let mut err: *mut c_char = std::ptr::null_mut();
            let rc = sqlite3_exec(self.handle, csql.as_ptr(), std::ptr::null_mut(), std::ptr::null_mut(), &mut err);
            if rc != SQLITE_OK {
                let msg = if err.is_null() { last_error(self.handle) } else {
                    let s = CStr::from_ptr(err).to_string_lossy().into_owned();
                    s
                };
                return Err(msg);
            }
        }
        Ok(())
    }

    pub fn prepare(&self, sql: &str) -> Result<Stmt, String> {
        let csql = CString::new(sql).map_err(|_| "invalid sql")?;
        let mut stmt: *mut c_void = std::ptr::null_mut();
        unsafe {
            let rc = sqlite3_prepare_v2(self.handle, csql.as_ptr(), -1, &mut stmt, std::ptr::null_mut());
            if rc != SQLITE_OK {
                return Err(last_error(self.handle));
            }
        }
        Ok(Stmt { conn: self, handle: stmt })
    }

    pub fn last_insert_rowid(&self) -> i64 {
        unsafe { sqlite3_last_insert_rowid(self.handle) }
    }

    pub fn changes(&self) -> i64 {
        unsafe { sqlite3_changes(self.handle) as i64 }
    }
}

impl Drop for Conn {
    fn drop(&mut self) {
        unsafe {
            sqlite3_close_v2(self.handle);
        }
    }
}

pub struct Stmt<'a> {
    conn: &'a Conn,
    handle: *mut c_void,
}

impl<'a> Stmt<'a> {
    pub fn bind_text(&mut self, idx: usize, val: &str) -> Result<(), String> {
        let cval = CString::new(val).map_err(|_| "invalid text")?;
        unsafe {
            let rc = sqlite3_bind_text(self.handle, idx as c_int, cval.as_ptr(), val.len() as c_int, std::ptr::null_mut());
            if rc != SQLITE_OK { return Err(last_error(self.conn.handle)); }
        }
        Ok(())
    }
    pub fn bind_null(&mut self, idx: usize) -> Result<(), String> {
        unsafe {
            let rc = sqlite3_bind_null(self.handle, idx as c_int);
            if rc != SQLITE_OK { return Err(last_error(self.conn.handle)); }
        }
        Ok(())
    }
    pub fn bind_double(&mut self, idx: usize, val: f64) -> Result<(), String> {
        unsafe {
            let rc = sqlite3_bind_double(self.handle, idx as c_int, val);
            if rc != SQLITE_OK { return Err(last_error(self.conn.handle)); }
        }
        Ok(())
    }
    pub fn bind_int(&mut self, idx: usize, val: i64) -> Result<(), String> {
        unsafe {
            let rc = sqlite3_bind_int64(self.handle, idx as c_int, val);
            if rc != SQLITE_OK { return Err(last_error(self.conn.handle)); }
        }
        Ok(())
    }

    pub fn query(&mut self) -> Result<Vec<Row>, String> {
        let mut rows = Vec::new();
        loop {
            let rc = unsafe { sqlite3_step(self.handle) };
            if rc == SQLITE_ROW {
                let ncols = self.column_count();
                let mut values = Vec::with_capacity(ncols);
                for i in 0..ncols {
                    values.push(self.column_value(i));
                }
                rows.push(Row { values });
            } else if rc == SQLITE_DONE {
                break;
            } else {
                unsafe { sqlite3_reset(self.handle); }
                return Err(last_error(self.conn.handle));
            }
        }
        unsafe { sqlite3_reset(self.handle); }
        Ok(rows)
    }

    fn column_count(&self) -> usize {
        // column count is not exported above; compute by scanning until NULL type
        let mut n = 0;
        unsafe {
            while sqlite3_column_type(self.handle, n) != -1 && n < 64 {
                n += 1;
                if sqlite3_column_type(self.handle, n) == 5 { break; }
            }
        }
        n
    }

    fn column_value(&self, i: usize) -> Value {
        unsafe {
            let ty = sqlite3_column_type(self.handle, i as c_int);
            match ty {
                1 => Value::Int(sqlite3_column_int64(self.handle, i as c_int)),
                2 => Value::Real(sqlite3_column_double(self.handle, i as c_int)),
                3 => {
                    let p = sqlite3_column_text(self.handle, i as c_int);
                    let n = sqlite3_column_bytes(self.handle, i as c_int);
                    if p.is_null() || n <= 0 { Value::Text(String::new()) } else {
                        let slice = std::slice::from_raw_parts(p, n as usize);
                        Value::Text(String::from_utf8_lossy(slice).into_owned())
                    }
                }
                _ => Value::Null,
            }
        }
    }
}

impl<'a> Drop for Stmt<'a> {
    fn drop(&mut self) {
        unsafe {
            sqlite3_finalize(self.handle);
        }
    }
}
RSEOF
echo ok"}

