#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/sha.h>
static unsigned char tgt[32];
static void h2b(const char*h, unsigned char*out){for(int i=0;i<32;i++){unsigned v;sscanf(h+2*i,"%2x",&v);out[i]=v;}}
int main(int argc,char**argv){
  h2b(argv[1],tgt);
  int maxlen=atoi(argv[2]);
  int lo=atoi(argv[3]), hi=atoi(argv[4]);
  int n=hi-lo+1;
  unsigned char buf[16];
  for(int L=1;L<=maxlen;L++){
    unsigned long long total=1ULL; for(int i=0;i<L;i++) total*=n;
    for(unsigned long long c=0;c<total;c++){
      unsigned long long x=c;
      for(int i=0;i<L;i++){ buf[i]=(unsigned char)(lo+(x%n)); x/=n; }
      unsigned char md[32]; SHA256(buf,L,md);
      if(!memcmp(md,tgt,32)){ printf("FOUND len=%d: ",L); for(int i=0;i<L;i++) putchar(buf[i]); printf("\n"); fflush(stdout);}
    }
    fprintf(stderr,"len %d done (%llu)\n",L,total);
  }
  return 0;
}
