// Card parsing: plain-text Markdown card format.
use std::path::{Path, PathBuf};

pub type Hash = [u8; 32];

pub fn hash_to_string(h: &Hash) -> String {
    hex::encode(h)
}

pub fn hash_from_string(s: &str) -> Option<Hash> {
    if s.len() != 64 {
        return None;
    }
    let b = hex::decode(s).ok()?;
    let mut out = [0u8; 32];
    out.copy_from_slice(&b);
    Some(out)
}

#[derive(Debug, Clone, PartialEq)]
pub enum CardContent {
    Basic { question: String, answer: String },
    Cloze { text: String, start: usize, end: usize },
}

#[derive(Debug, Clone)]
pub struct Location {
    pub file_path: PathBuf,
    pub line_start: usize,
    pub line_end: usize,
}

#[derive(Debug, Clone)]
pub struct Card {
    pub hash: Hash,
    pub family_hash: Option<Hash>,
    pub deck_name: String,
    pub location: Location,
    pub content: CardContent,
}

#[derive(Debug, Clone)]
pub struct ParseError {
    pub message: String,
    pub path: PathBuf,
    pub line: usize,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.message)
    }
}

fn trim(s: &str) -> String {
    s.trim().to_string()
}

/// The kind of tag found at the start of a line.
#[derive(Debug, Clone, Copy, PartialEq)]
enum Tag {
    Question,
    Answer,
    Cloze,
}

fn tag_of(line: &str) -> Option<Tag> {
    if line.starts_with("Q:") {
        Some(Tag::Question)
    } else if line.starts_with("A:") {
        Some(Tag::Answer)
    } else if line.starts_with("C:") {
        Some(Tag::Cloze)
    } else {
        None
    }
}

fn content_after(line: &str) -> &str {
    &line[2..]
}

pub fn parse_file(path: &Path, deck_name: &str, content: &str) -> Result<Vec<Card>, ParseError> {
    let lines: Vec<&str> = content.lines().collect();
    let mut cards: Vec<Card> = Vec::new();
    #[derive(Debug)]
    enum State {
        Empty,
        Question { start: usize, lines: Vec<String> },
        Answer { start: usize, q: Vec<String>, a: Vec<String> },
        Cloze { start: usize, lines: Vec<String> },
    }
    let mut state = State::Empty;

    let err = |line: usize, message: &str| -> ParseError {
        ParseError { message: message.to_string(), path: path.to_path_buf(), line: line + 1 }
    };

    macro_rules! push_basic {
        ($st:expr, $end:expr) => {{
            let (s, q, a) = match $st {
                State::Answer { start, q, a } => (start, q, a),
                _ => unreachable!(),
            };
            let question = trim(&q.join("\n"));
            let answer = trim(&a.join("\n"));
            let content = CardContent::Basic { question, answer };
            cards.push(Card {
                hash: card_hash(&content),
                family_hash: None,
                deck_name: deck_name.to_string(),
                location: Location {
                    file_path: path.to_path_buf(),
                    line_start: s,
                    line_end: $end,
                },
                content,
            });
        }};
    }
    macro_rules! push_cloze {
        ($st:expr, $end:expr) => {{
            let (s, ls) = match $st {
                State::Cloze { start, lines } => (start, lines),
                _ => unreachable!(),
            };
            let text = trim(&ls.join("\n"));
            let (clean, dels) = parse_cloze(&text);
            if dels.is_empty() {
                return Err(err(s, "Cloze card must contain at least one cloze deletion."));
            }
            for (start, end) in dels {
                let content = CardContent::Cloze { text: clean.clone(), start, end };
                cards.push(Card {
                    hash: card_hash(&content),
                    family_hash: Some(family_hash(&clean)),
                    deck_name: deck_name.to_string(),
                    location: Location {
                        file_path: path.to_path_buf(),
                        line_start: s,
                        line_end: $end,
                    },
                    content: content.clone(),
                });
            }
        }};
    }

    for (idx, line) in lines.iter().enumerate() {
        match tag_of(line) {
            Some(Tag::Question) => {
                match state {
                    State::Question { start, .. } => {
                        return Err(err(idx, "New question without answer."));
                    }
                    State::Answer { .. } => {
                        let st = std::mem::replace(&mut state, State::Empty);
                        push_basic!(st, idx);
                        state = State::Question { start: idx, lines: vec![content_after(line).to_string()] };
                    }
                    State::Cloze { .. } => {
                        let st = std::mem::replace(&mut state, State::Empty);
                        push_cloze!(st, idx);
                        state = State::Question { start: idx, lines: vec![content_after(line).to_string()] };
                    }
                    State::Empty => {
                        state = State::Question { start: idx, lines: vec![content_after(line).to_string()] };
                    }
                }
            }
            Some(Tag::Answer) => {
                match state {
                    State::Empty => {
                        return Err(err(idx, "Found answer tag without a question."));
                    }
                    State::Question { start, lines: q } => {
                        state = State::Answer { start, q, a: vec![content_after(line).to_string()] };
                    }
                    State::Answer { start, .. } => {
                        return Err(err(idx, "Found answer tag while reading an answer."));
                    }
                    State::Cloze { .. } => {
                        return Err(err(idx, "Found answer tag while reading a cloze card."));
                    }
                }
            }
            Some(Tag::Cloze) => {
                match state {
                    State::Question { .. } => {
                        return Err(err(idx, "Found cloze tag while reading a question."));
                    }
                    State::Answer { .. } => {
                        let st = std::mem::replace(&mut state, State::Empty);
                        push_basic!(st, idx);
                        state = State::Cloze { start: idx, lines: vec![content_after(line).to_string()] };
                    }
                    State::Cloze { .. } => {
                        let st = std::mem::replace(&mut state, State::Empty);
                        push_cloze!(st, idx);
                        state = State::Cloze { start: idx, lines: vec![content_after(line).to_string()] };
                    }
                    State::Empty => {
                        state = State::Cloze { start: idx, lines: vec![content_after(line).to_string()] };
                    }
                }
            }
            None => {
                match &mut state {
                    State::Question { lines, .. } => lines.push(line.to_string()),
                    State::Answer { a, .. } => a.push(line.to_string()),
                    State::Cloze { lines, .. } => lines.push(line.to_string()),
                    State::Empty => {}
                }
            }
        }
    }
    let last = lines.len().saturating_sub(1);
    match std::mem::replace(&mut state, State::Empty) {
        State::Answer { .. } => {
            let st = state;
            push_basic!(st, last);
        }
        State::Cloze { .. } => {
            let st = state;
            push_cloze!(st, last);
        }
        State::Question { start, .. } => {
            return Err(err(start, "File ended while reading a question without an answer."));
        }
        State::Empty => {}
    }
    Ok(cards)
}

/// Parse cloze deletions out of a text. Returns the cleaned text and the byte
/// ranges (inclusive) of each deletion.
pub fn parse_cloze(text: &str) -> (String, Vec<(usize, usize)>) {
    let bytes = text.as_bytes();
    let mut out: Vec<u8> = Vec::with_capacity(bytes.len());
    let mut dels: Vec<(usize, usize)> = Vec::new();
    let mut i = 0usize;
    let mut cur: Option<usize> = None;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'!' && i + 1 < bytes.len() && bytes[i + 1] == b'[' {
            match match_image(bytes, i) {
                Some(end) => {
                    out.extend_from_slice(&bytes[i..end]);
                    i = end;
                }
                None => {
                    out.extend_from_slice(&bytes[i..]);
                    i = bytes.len();
                }
            }
            continue;
        }
        if b == b'[' {
            if cur.is_none() {
                cur = Some(out.len());
            }
            i += 1;
            continue;
        }
        if b == b']' {
            if let Some(s) = cur.take() {
                let e = out.len().wrapping_sub(1);
                dels.push((s, e));
            }
            i += 1;
            continue;
        }
        out.push(b);
        i += 1;
    }
    (String::from_utf8_lossy(&out).into_owned(), dels)
}

/// Try to match a markdown image starting at `i` (which must point at `!`).
/// Returns the index one past the end of the consumed region.
fn match_image(bytes: &[u8], i: usize) -> Option<usize> {
    let len = bytes.len();
    let mut j = i + 2;
    if j > len {
        return None;
