                cards.push(Card {
                    hash: card_hash(&content),
                    family_hash: Some(family_hash(&clean)),
                    deck_name: deck_name.to_string(),
                    location: Location {
                        file_path: path.to_path_buf(),
                        line_start: s,
                        line_end: $end,
                    },
                    content: content.clone(),
                });
            }
        }};
    }

    for (idx, line) in lines.iter().enumerate() {
        match tag_of(line) {
            Some(Tag::Question) => {
                match state {
                    State::Question { start, .. } => {
                        return Err(err(idx, "New question without answer."));
                    }
                    State::Answer { .. } => {
                        let st = std::mem::replace(&mut state, State::Empty);
                        push_basic!(st, idx);
                        state = State::Question { start: idx, lines: vec![content_after(line).to_string()] };
