// Content hashing. Cards are identified by the SHA-256 of their text.
use crate::cards::Hash;
use sha2::{Sha256, Digest};

/// Hash of a whole card (the concatenation of its fields).
pub fn card_hash(content: &crate::cards::CardContent) -> Hash {
    let mut hasher = Sha256::new();
    match content {
        crate::cards::CardContent::Basic { question, answer } => {
            hasher.update(question.as_bytes());
            hasher.update(answer.as_bytes());
        }
        crate::cards::CardContent::Cloze { text, start, end } => {
            hasher.update(text.as_bytes());
            hasher.update(start.to_le_bytes());
            hasher.update(end.to_le_bytes());
        }
    }
    let out = hasher.finalize();
    let mut h = [0u8; 32];
    h.copy_from_slice(&out);
    h
}

/// Hash of a cloze family (the shared text of all its cards).
pub fn family_hash(text: &str) -> Hash {
    let mut hasher = Sha256::new();
    hasher.update(text.as_bytes());
    let out = hasher.finalize();
    let mut h = [0u8; 32];
    h.copy_from_slice(&out);
    h
}
