        qm=re.search(r'<div class="(question|prompt) rich-text">(.*?)</div>\n', b, re.S)
        q=re.sub(r'<[^>]*>','',qm.group(2)).strip() if qm else '?'
        if 'value="Forgot"' in b:
            g = grades[len(seen)] if len(seen)<len(grades) else 'Good'
            urllib.request.urlopen(urllib.request.Request(base, data=('action='+g).encode()))
            seen.append((q, b[b.find('<div class="card-content">'):b.find('<div class="controls">')]))
        elif 'value="Reveal"' in b:
            urllib.request.urlopen(urllib.request.Request(base, data=b'action=Reveal'))
            seen.append(q)
        else:
            urllib.request.urlopen(urllib.request.Request(base, data=b'action=End'))
            continue
    return dict(total=None, cards=seen)
