{"command": "cat > src/collection.rs <<'RSEOF'
// Collection loading: scan markdown decks, parse cards, load TeX macros and
// validate media references.
use std::path::{Path, PathBuf};
use crate::cards::{Card, Hash, hash_from_string};

#[derive(Debug, Clone)]
pub struct TexMacro {
    pub name: String,
    pub body: String,
}

#[derive(Debug)]
pub struct Collection {
    pub dir: PathBuf,
    pub cards: Vec<Card>,
    pub macros: Vec<TexMacro>,
}

fn list_files(root: &Path, out: &mut Vec<PathBuf>) -> std::io::Result<()> {
    let mut entries: Vec<std::fs::DirEntry> = std::fs::read_dir(root)?
        .filter_map(|e| e.ok())
        .collect();
    entries.sort_by(|a, b| a.path().as_os_str().as_encoded_bytes().cmp(b.path().as_os_str().as_encoded_bytes()));
    for e in entries {
        let p = e.path();
        if p.is_dir() {
            list_files(&p, out)?;
        } else if p.extension().map(|x| x == "md").unwrap_or(false) {
            out.push(p);
        }
    }
    Ok(())
}

pub fn load_macros(root: &Path) -> Vec<TexMacro> {
    let path = root.join("macros.tex");
    let content = match std::fs::read_to_string(&path) {
        Ok(c) => c,
        Err(_) => return Vec::new(),
    };
    let mut macros = Vec::new();
    for line in content.lines() {
        if line.starts_with('%') {
            continue;
        }
        if let Some((name, body)) = line.split_once(' ') {
            macros.push(TexMacro { name: name.to_string(), body: body.to_string() });
        }
    }
    macros
}

pub struct MediaError {
    pub reference: String,
    pub path: PathBuf,
    pub line: usize,
}

pub fn load(dir: &Path) -> Result<Collection, LoadError> {
    let mut files = Vec::new();
    list_files(dir, &mut files).map_err(|e| LoadError::Io(format!("{}", e)))?;
    let mut all: Vec<Card> = Vec::new();
    for f in &files {
        let content = std::fs::read_to_string(f).map_err(|e| LoadError::Io(format!("{}", e)))?;
        let deck_name = f.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string();
        let cards = crate::cards::parse_file(f, &deck_name, &content).map_err(LoadError::Parse)?;
        all.extend(cards);
    }
    // dedupe by hash, last wins
    let mut map: std::collections::HashMap<Hash, Card> = std::collections::HashMap::new();
    for c in all {
        map.insert(c.hash, c);
    }
    let mut cards: Vec<Card> = map.into_values().collect();
    cards.sort_by(|a, b| a.hash.cmp(&b.hash));
    // media validation
    let mut missing: Vec<MediaError> = Vec::new();
    for c in &cards {
        let refs = match &c.content {
            crate::cards::CardContent::Basic { question, answer } => {
                let mut v = crate::cards::media_references(question);
                v.extend(crate::cards::media_references(answer));
                v
            }
            crate::cards::CardContent::Cloze { text, .. } => crate::cards::media_references(text),
        };
        for r in refs {
            if !media_exists(dir, &c.location.file_path, &r) {
                missing.push(MediaError {
                    reference: r,
                    path: c.location.file_path.clone(),
                    line: c.location.line_start,
                });
            }
        }
    }
    if !missing.is_empty() {
        missing.sort_by(|a, b| a.reference.cmp(&b.reference));
        return Err(LoadError::Media(missing));
    }
    let macros = load_macros(dir);
    Ok(Collection { dir: dir.to_path_buf(), cards, macros })
}

fn media_exists(root: &Path, file: &Path, reference: &str) -> bool {
    let path = if let Some(rest) = reference.strip_prefix("@/") {
        root.join(rest)
    } else {
        file.parent().unwrap_or(root).join(reference)
    };
    path.is_file()
}

#[derive(Debug)]
pub enum LoadError {
    Io(String),
    Parse(crate::cards::ParseError),
    Media(Vec<MediaError>),
}

impl std::fmt::Display for LoadError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            LoadError::Io(e) => write!(f, "I/O error: {}", e),
            LoadError::Parse(e) => write!(f, "Parse error: {}. Location: {}:{}",
                e.message, e.path.display(), e.line),
            LoadError::Media(list) => {
                write!(f, "Missing media files referenced in cards:")?;
                for m in list {
                    write!(f, "\n  - {} (referenced in {}:{})", m.reference, m.path.display(), m.line)?;
                }
                Ok(())
            }
        }
    }
}

// --- database ---

pub const SCHEMA: &str = "CREATE TABLE cards (
    card_hash text primary key,
    added_at text not null,
    last_reviewed_at text,
    stability real,
    difficulty real,
    interval_raw real,
    interval_days integer,
    due_date text,
    review_count integer not null
) strict
CREATE TABLE sessions (
    session_id integer primary key,
    started_at text not null,
    ended_at text not null
) strict
CREATE TABLE reviews (
    review_id integer primary key,
    session_id integer not null
        references sessions (session_id)
        on update cascade
        on delete cascade,
    card_hash text not null
        references cards (card_hash)
        on update cascade
        on delete cascade,
    reviewed_at text not null,
    grade text not null,
    stability real not null,
    difficulty real not null,
    interval_raw real not null,
    interval_days integer not null,
    due_date text not null
) strict";

#[derive(Debug, Clone)]
pub struct Performance {
    pub last_reviewed_at: String,
    pub stability: f64,
    pub difficulty: f64,
    pub interval_raw: f64,
    pub interval_days: i64,
    pub due_date: String,
    pub review_count: i64,
}

pub fn open_db(dir: &Path) -> Result<crate::db::Conn, String> {
