// Minimal Markdown -> HTML renderer plus KaTeX/Tex macro handling.
pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

pub struct Ctx<'a> {
    pub macros: &'a [crate::collection::TexMacro],
    pub base_url: String,
}

pub fn is_audio(url: &str) -> bool {
    let l = url.to_ascii_lowercase();
    l.ends_with(".mp3") || l.ends_with(".ogg") || l.ends_with(".wav")
}

pub fn media_url(ctx: &Ctx, deck_file: &std::path::Path, root: &std::path::Path, url: &str) -> String {
    let rel = if let Some(rest) = url.strip_prefix("@/") {
        rest.to_string()
    } else if url.starts_with("http://") || url.starts_with("https://") {
        return url.to_string();
    } else {
        let dir = deck_file.parent().unwrap_or(root);
        let abs = dir.join(url);
        match abs.strip_prefix(root) {
            Ok(r) => r.to_string_lossy().into_owned(),
            Err(_) => url.to_string(),
        }
    };
    format!("{}/file/{}", ctx.base_url, rel)
}

/// Split math spans out of a markdown text: `$...$` and `$$...$$`.
pub enum Piece {
    Text(String),
    Inline(String),
    Display(String),
}

pub fn split_math(s: &str) -> Vec<Piece> {
    let b: Vec<char> = s.chars().collect();
    let mut out = Vec::new();
    let mut buf = String::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == '$' {
            if i + 1 < b.len() && b[i + 1] == '$' {
                if let Some(end) = find_seq(&b, i + 2, '$', 2) {
                    if !buf.is_empty() { out.push(Piece::Text(std::mem::take(&mut buf))); }
                    out.push(Piece::Display(b[i + 2..end].iter().collect()));
                    i = end + 2;
                    continue;
                }
            } else {
                if let Some(end) = find_seq(&b, i + 1, '$', 1) {
                    if !buf.is_empty() { out.push(Piece::Text(std::mem::take(&mut buf))); }
                    out.push(Piece::Inline(b[i + 1..end].iter().collect()));
                    i = end + 1;
                    continue;
                }
            }
        }
        buf.push(b[i]);
        i += 1;
    }
    if !buf.is_empty() { out.push(Piece::Text(buf)); }
    out
}

fn find_seq(b: &[char], from: usize, c: char, n: usize) -> Option<usize> {
    let mut i = from;
    let mut count = 0;
    while i < b.len() {
        if b[i] == c {
            count += 1;
            if count == n {
                return Some(i - n + 1);
            }
        } else {
            count = 0;
        }
        i += 1;
    }
    None
}

/// Render a markdown text to HTML (block level).
pub fn render_markdown(src: &str, f: &dyn Fn(&str) -> String) -> String {
    let mut out = String::new();
    let lines: Vec<&str> = src.split('\n').collect();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let t = line.trim_start();
        if t.is_empty() {
            i += 1;
            continue;
        }
        if t.starts_with('#') {
            let mut level = 0;
            for c in t.chars() {
                if c == '#' { level += 1 } else { break }
            }
            let text = t[level..].trim();
            let tag = match level { 1 => "h1", 2 => "h2", 3 => "h3", 4 => "h4", 5 => "h5", _ => "h6" };
            out.push_str(&format!("<{0}>{1}</{0}>\n", tag, f(text)));
            i += 1;
            continue;
        }
        if t.starts_with("```") {
            let lang = t[3..].trim();
            let mut body = Vec::new();
            i += 1;
            while i < lines.len() && !lines[i].trim_start().starts_with("```") {
                body.push(lines[i]);
                i += 1;
            }
            i += 1;
            let class = if lang.is_empty() { String::new() } else { format!(" class=\"language-{}\"", lang) };
            out.push_str(&format!("<pre><code{0}>{1}\n</code></pre>\n", class, escape_html(&body.join("\n"))));
            continue;
        }
        if t.starts_with('>') {
            let mut body = Vec::new();
            while i < lines.len() && lines[i].trim_start().starts_with('>') {
                let l = lines[i].trim_start();
                body.push(l.strip_prefix('>').unwrap_or("").strip_prefix(' ').unwrap_or(l).to_string());
                i += 1;
            }
            out.push_str("<blockquote>\n");
            out.push_str(&render_markdown(&body.join("\n"), f));
            out.push_str("</blockquote>\n");
            continue;
        }
        if t.starts_with('|') && lines.get(i + 1).map(|l| l.trim_start().starts_with('|')).unwrap_or(false) {
            let header: Vec<&str> = t.trim_matches('|').split('|').map(|x| x.trim()).collect();
            i += 2;
            let mut rows = Vec::new();
