            out.push_str("<blockquote>\n");
            out.push_str(&render_markdown(&body.join("\n"), f));
            out.push_str("</blockquote>\n");
            continue;
        }
        if t.starts_with('|') && lines.get(i + 1).map(|l| l.trim_start().starts_with('|')).unwrap_or(false) {
            let header: Vec<&str> = t.trim_matches('|').split('|').map(|x| x.trim()).collect();
            i += 2;
            let mut rows = Vec::new();
            while i < lines.len() && lines[i].trim_start().starts_with('|') {
                rows.push(lines[i].trim_matches('|').split('|').map(|x| x.trim()).collect::<Vec<&str>>());
                i += 1;
            }
            out.push_str("<table><thead><tr>");
            for h in &header { out.push_str(&format!("<th>{}</th>", f(h))); }
            out.push_str("</tr></thead><tbody>\n");
            for r in &rows {
                out.push_str("<tr>");
                for cell in r { out.push_str(&format!("<td>{}</td>", f(cell))); }
                out.push_str("</tr>\n");
            }
            out.push_str("</tbody></table>\n");
            continue;
        }
        if t.starts_with("- ") || t.starts_with("* ") {
            let marker = if t.starts_with("- ") { "- " } else { "* " };
            let mut items = Vec::new();
            while i < lines.len() && lines[i].trim_start().starts_with(marker) {
                items.push(lines[i].trim_start()[2..].trim().to_string());
                i += 1;
            }
            out.push_str("<ul>\n");
            for it in &items { out.push_str(&format!("<li>{}</li>\n", f(it))); }
            out.push_str("</ul>\n");
            continue;
        }
        if t.starts_with("    ") {
            let mut body = Vec::new();
            while i < lines.len() && lines[i].starts_with("    ") {
                body.push(&lines[i][4..]);
                i += 1;
            }
            out.push_str(&format!("<pre><code>{}</code></pre>\n", escape_html(&body.join("\n"))));
            continue;
        }
        // paragraph
        let mut body = Vec::new();
        while i < lines.len() && !lines[i].trim().is_empty() {
            body.push(lines[i]);
            i += 1;
        }
        out.push_str(&format!("<p>{}</p>\n", f(&body.join("\n"))));
    }
    out
}

/// Inline markdown: emphasis, strong, code, links, images, audio.
pub fn render_inline(src: &str) -> String {
    let mut out = String::new();
    let b: Vec<char> = src.chars().collect();
    let mut i = 0;
    while i < b.len() {
        if b[i] == '`' {
            if let Some(end) = b[i + 1..].iter().position(|&c| c == '`') {
                out.push_str(&format!("<code>{}</code>", escape_html(&b[i + 1..i + 1 + end].iter().collect::<String>())));
                i = i + end + 2;
                continue;
            }
        }
        if b[i] == '!' && i + 1 < b.len() && b[i + 1] == '[' {
            if let Some(end) = crate::cards::match_image_bytes(&b, i) {
                let inner: String = b[i + 2..end - 1].iter().collect();
                let (alt, url, title) = split_link(&inner);
                if is_audio(&url) {
                    out.push_str(&format!("<audio controls src=\"{}\" title=\"{}\"></audio>", url, escape_html(&title)));
                    if !alt.is_empty() { out.push_str(&escape_html(&alt)); }
                } else if title.is_empty() {
                    out.push_str(&format!("<img src=\"{}\" alt=\"{}\" />", url, escape_html(&alt)));
                } else {
                    out.push_str(&format!("<img src=\"{}\" alt=\"{}\" title=\"{}\" />", url, escape_html(&alt), escape_html(&title)));
                }
                i = end;
                continue;
            }
        }
        if b[i] == '[' {
            if let Some(end) = crate::cards::match_link_bytes(&b, i) {
                let inner: String = b[i + 1..end - 1].iter().collect();
                let (text, url, _t) = split_link(&inner);
                out.push_str(&format!("<a href=\"{}\">{}</a>", url, f_inline(&text)));
                i = end;
                continue;
            }
        }
        if b[i] == '*' {
            if i + 1 < b.len() && b[i + 1] == '*' {
                if let Some(end) = find_sub(&b, i + 2, "**") {
                    out.push_str(&format!("<strong>{}</strong>", f_inline(&b[i + 2..end].iter().collect::<String>())));
                    i = end + 2;
                    continue;
                }
            } else if let Some(end) = b[i + 1..].iter().position(|&c| c == '*') {
                out.push_str(&format!("<em>{}</em>", f_inline(&b[i + 1..i + 1 + end].iter().collect::<String>())));
                i = i + end + 2;
                continue;
            }
        }
        if b[i] == '_' {
            if let Some(end) = b[i + 1..].iter().position(|&c| c == '_') {
                out.push_str(&format!("<em>{}</em>", f_inline(&b[i + 1..i + 1 + end].iter().collect::<String>())));
                i = i + end + 2;
                continue;
            }
        }
        out.push(if b[i] == '&' { "&amp;".to_string() } else if b[i] == '<' { "&lt;".to_string() } else if b[i] == '>' { "&gt;".to_string() } else { b[i].to_string() });
        i += 1;
    }
    out
}

fn f_inline(s: &str) -> String {
    render_inline(s)
}

fn find_sub(b: &[char], from: usize, pat: &str) -> Option<usize> {
    let p: Vec<char> = pat.chars().collect();
    let mut i = from;
    while i + p.len() <= b.len() {
        if b[i..i + p.len()] == p[..] { return Some(i); }
        i += 1;
    }
    None
}

fn split_link(inner: &str) -> (String, String, String) {
    match inner.find("](") {
        Some(pos) => {
            let rest = &inner[pos + 2..];
            let (url, title) = match rest.rfind(')') {
                Some(c) => {
                    let u = &rest[..c];
                    match u.rfind(" \"") {
                        Some(t) if t > 0 => (u[..t].to_string(), u[t + 2..].trim_matches('"').to_string()),
                        _ => (u.to_string(), String::new()),
                    }
                }
                None => (rest.to_string(), String::new()),
            };
            (inner[..pos].to_string(), url, title)
        }
        None => (inner.to_string(), String::new(), String::new()),
    }
}

pub fn render_text(src: &str) -> String {
    render_markdown(src, &|s: &str| render_inline(s))
}

pub fn render_math_span(text: &str, display: bool) -> String {
    let cls = if display { "math math-display" } else { "math math-inline" };
    format!("<span class=\"{}\">{}</span>", cls, escape_html(text))
}

pub fn render_rich(src: &str, ctx: &Ctx) -> String {
    let mut out = String::new();
    for piece in split_math(src) {
        match piece {
            Piece::Text(t) => out.push_str(&render_text(&t)),
            Piece::Inline(t) => out.push_str(&render_math_span(&t, false)),
            Piece::Display(t) => out.push_str(&render_math_span(&t, true)),
        }
    }
    out
}
