        let mut st = conn.prepare("SELECT count(*) FROM cards WHERE due_date IS NOT NULL AND last_reviewed_at IS NOT NULL AND substr(last_reviewed_at, 1, 10) = ?")?;
        st.bind_text(1, today)?;
        st.query()?.first().and_then(|r| r.int(0)).unwrap_or(0)
    };
    let out = StatsOut {
        cardsInDeckCount: col.cards.len(),
        cardsInDbCount: cards_in_db as usize,
        texMacroCount: col.macros.len(),
        cardsReviewedTodayCount: reviewed_today,
    };
    Ok(serde_json::to_string_pretty(&out).map_err(|e| e.to_string())?)
}

pub fn orphans_list(conn: &crate::db::Conn, col: &crate::collection::Collection) -> Result<Vec<String>, String> {
    let mut st = conn.prepare("SELECT card_hash FROM cards")?;
    let rows = st.query()?;
    let mut db_hashes: Vec<String> = Vec::new();
    for r in rows {
        let h = r.text(0).ok_or_else(|| "invalid hash in performance database".to_string())?;
        db_hashes.push(h);
    }
    let deck: std::collections::HashSet<String> = col.cards.iter()
        .map(|c| crate::cards::hash_to_string(&c.hash)).collect();
    let mut orphans: Vec<String> = Vec::new();
    for h in db_hashes {
        if crate::cards::hash_from_string(&h).is_none() {
            return Err("invalid hash in performance database".to_string());
        }
        if !deck.contains(&h) {
            orphans.push(h);
        }
    }
    orphans.sort();
    Ok(orphans)
}

pub fn orphans_delete(conn: &crate::db::Conn, col: &crate::collection::Collection) -> Result<Vec<String>, String> {
    let orphans = orphans_list(conn, col)?;
    for h in &orphans {
        let mut st = conn.prepare("DELETE FROM cards WHERE card_hash = ?")?;
        st.bind_text(1, h)?;
        st.query()?;
    }
    Ok(orphans)
}

