        let content = match &c.content {
            crate::cards::CardContent::Basic { question, answer } => {
                ContentOut::Basic(BasicOut { question: question.clone(), answer: answer.clone() })
            }
            crate::cards::CardContent::Cloze { text, start, end } => {
                ContentOut::Cloze(ClozeOut { text: text.clone(), start: *start, end: *end })
            }
        };
        cards.push(CardOut {
            hash: crate::cards::hash_to_string(&c.hash),
            familyHash: c.family_hash.as_ref().map(crate::cards::hash_to_string),
