                lineStart: c.location.line_start,
                lineEnd: c.location.line_end,
            },
            content,
            performance: perf.map(|p| PerformanceOut {
                lastReviewedAt: p.last_reviewed_at,
                stability: p.stability,
                difficulty: p.difficulty,
                intervalRaw: p.interval_raw,
                intervalDays: p.interval_days,
                dueDate: p.due_date,
                reviewCount: p.review_count,
            }),
        });
    }
    let mut sessions = Vec::new();
    {
        let mut st = conn.prepare("SELECT session_id, started_at, ended_at FROM sessions ORDER BY session_id")?;
        let rows = st.query()?;
        for r in rows {
            let sid = r.int(0).unwrap_or(0);
            let started = r.text(1).unwrap_or_default();
            let ended = r.text(2).unwrap_or_default();
            let mut reviews = Vec::new();
            {
                let mut st2 = conn.prepare("SELECT review_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date FROM reviews WHERE session_id = ? ORDER BY review_id")?;
                st2.bind_int(1, sid)?;
                for rr in st2.query()? {
                    reviews.push(ReviewOut {
                        reviewId: rr.int(0).unwrap_or(0),
                        hash: rr.text(1).unwrap_or_default(),
                        reviewedAt: rr.text(2).unwrap_or_default(),
                        grade: capitalize(&rr.text(3).unwrap_or_default()),
                        stability: rr.real(4).unwrap_or(0.0),
                        difficulty: rr.real(5).unwrap_or(0.0),
                        intervalRaw: rr.real(6).unwrap_or(0.0),
                        intervalDays: rr.int(7).unwrap_or(0),
                        dueDate: rr.text(8).unwrap_or_default(),
                    });
                }
            }
            sessions.push(SessionOut { sessionId: sid, startedAt: started, endedAt: ended, reviews });
        }
    }
    let out = ExportOut { cards, sessions };
    serde_json::to_string_pretty(&out).map_err(|e| e.to_string())
}

fn capitalize(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}
