        db_hashes.push(h);
    }
    let deck: std::collections::HashSet<String> = col.cards.iter()
        .map(|c| crate::cards::hash_to_string(&c.hash)).collect();
    let mut orphans: Vec<String> = Vec::new();
    for h in db_hashes {
        if crate::cards::hash_from_string(&h).is_none() {
            return Err("invalid hash in performance database".to_string());
        }
        if !deck.contains(&h) {
            orphans.push(h);
        }
    }
    orphans.sort();
    Ok(orphans)
}

pub fn orphans_delete(conn: &crate::db::Conn, col: &crate::collection::Collection) -> Result<Vec<String>, String> {
    let orphans = orphans_list(conn, col)?;
    for h in &orphans {
        let mut st = conn.prepare("DELETE FROM cards WHERE card_hash = ?")?;
        st.bind_text(1, h)?;
        st.query()?;
    }
    Ok(orphans)
}

// --- export ---

#[derive(Serialize)]
struct LocationOut {
    filePath: String,
    lineStart: usize,
    lineEnd: usize,
}

#[derive(Serialize)]
struct BasicOut {
    question: String,
    answer: String,
}

#[derive(Serialize)]
struct ClozeOut {
    text: String,
    start: usize,
    end: usize,
}

#[derive(Serialize)]
#[serde(untagged)]
enum ContentOut {
    Basic(BasicOut),
    Cloze(ClozeOut),
}

#[derive(Serialize)]
struct PerformanceOut {
    lastReviewedAt: String,
    stability: f64,
    difficulty: f64,
    intervalRaw: f64,
    intervalDays: i64,
    dueDate: String,
    reviewCount: i64,
}

#[derive(Serialize)]
struct CardOut {
    hash: String,
    familyHash: Option<String>,
    deckName: String,
    location: LocationOut,
    content: ContentOut,
    performance: Option<PerformanceOut>,
}

#[derive(Serialize)]
struct ReviewOut {
    reviewId: i64,
    hash: String,
    reviewedAt: String,
    grade: String,
    stability: f64,
    difficulty: f64,
    intervalRaw: f64,
    intervalDays: i64,
    dueDate: String,
}

#[derive(Serialize)]
struct SessionOut {
    sessionId: i64,
    startedAt: String,
    endedAt: String,
    reviews: Vec<ReviewOut>,
}

#[derive(Serialize)]
struct ExportOut {
    cards: Vec<CardOut>,
    sessions: Vec<SessionOut>,
}

pub fn export(conn: &crate::db::Conn, col: &crate::collection::Collection) -> Result<String, String> {
    let mut cards = Vec::new();
    for c in &col.cards {
        let perf = crate::collection::get_performance(conn, &c.hash)?;
        let content = match &c.content {
            crate::cards::CardContent::Basic { question, answer } => {
                ContentOut::Basic(BasicOut { question: question.clone(), answer: answer.clone() })
            }
            crate::cards::CardContent::Cloze { text, start, end } => {
                ContentOut::Cloze(ClozeOut { text: text.clone(), start: *start, end: *end })
            }
        };
        cards.push(CardOut {
            hash: crate::cards::hash_to_string(&c.hash),
            familyHash: c.family_hash.as_ref().map(crate::cards::hash_to_string),
            deckName: c.deck_name.clone(),
            location: LocationOut {
                filePath: c.location.file_path.display().to_string(),
                lineStart: c.location.line_start,
                lineEnd: c.location.line_end,
            },
            content,
            performance: perf.map(|p| PerformanceOut {
                lastReviewedAt: p.last_reviewed_at,
                stability: p.stability,
                difficulty: p.difficulty,
                intervalRaw: p.interval_raw,
                intervalDays: p.interval_days,
                dueDate: p.due_date,
                reviewCount: p.review_count,
            }),
        });
    }
    let mut sessions = Vec::new();
    {
        let mut st = conn.prepare("SELECT session_id, started_at, ended_at FROM sessions ORDER BY session_id")?;
        let rows = st.query()?;
        for r in rows {
            let sid = r.int(0).unwrap_or(0);
            let started = r.text(1).unwrap_or_default();
            let ended = r.text(2).unwrap_or_default();
            let mut reviews = Vec::new();
            {
                let mut st2 = conn.prepare("SELECT review_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date FROM reviews WHERE session_id = ? ORDER BY review_id")?;
                st2.bind_int(1, sid)?;
                for rr in st2.query()? {
                    reviews.push(ReviewOut {
                        reviewId: rr.int(0).unwrap_or(0),
                        hash: rr.text(1).unwrap_or_default(),
                        reviewedAt: rr.text(2).unwrap_or_default(),
                        grade: capitalize(&rr.text(3).unwrap_or_default()),
                        stability: rr.real(4).unwrap_or(0.0),
                        difficulty: rr.real(5).unwrap_or(0.0),
                        intervalRaw: rr.real(6).unwrap_or(0.0),
                        intervalDays: rr.int(7).unwrap_or(0),
                        dueDate: rr.text(8).unwrap_or_default(),
                    });
                }
            }
            sessions.push(SessionOut { sessionId: sid, startedAt: started, endedAt: ended, reviews });
        }
    }
    let out = ExportOut { cards, sessions };
    serde_json::to_string_pretty(&out).map_err(|e| e.to_string())
}

fn capitalize(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}
