// Web server for drilling.
use std::path::Path;
use std::io::{Read, Write};

pub fn run_drill(dir: &Path, m: &clap::ArgMatches) -> Result<(), String> {
    let col = crate::collection::load(dir).map_err(|e| e.to_string())?;
    let conn = crate::collection::open_db(dir)?;
    crate::collection::sync_cards(&conn, dir, &col.cards)?;
    let port: u16 = m.get_one::<String>("port").and_then(|s| s.parse().ok()).unwrap_or(8000);
    let host = m.get_one::<String>("host").cloned().unwrap_or_else(|| "127.0.0.1".to_string());
    let limit = m.get_one::<String>("card-limit").and_then(|s| s.parse::<usize>().ok());
    let new_limit = m.get_one::<String>("new-card-limit").and_then(|s| s.parse::<usize>().ok());
    let from_deck = m.get_one::<String>("from-deck").cloned();
    let bury = m.get_one::<String>("bury-siblings").map(|s| s == "true").unwrap_or(true);
    let open_browser = m.get_one::<String>("open-browser").map(|s| s == "true").unwrap_or(true);
    let binary_controls = m.get_one::<String>("answer-controls").map(|s| s == "binary").unwrap_or(false);

    let session = crate::web::session::select(&conn, &col, crate::timeutil::today_date(), limit, new_limit, from_deck.as_deref(), bury);
    if session.is_empty() {
        println!("No cards due today.");
        return Ok(());
    }
    crate::web::server::serve(&conn, &col, session, &host, port, open_browser, binary_controls)
}

pub mod session {
    use crate::cards::{Card, CardContent, Hash};
    use std::collections::HashMap;

    fn shuffle<T>(v: &mut Vec<T>) {
        // xorshift based shuffle so behaviour is reproducible-ish and independent
        let mut seed = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64).unwrap_or(0x1234_5678_9abc_def0);
        for i in (1..v.len()).rev() {
            seed ^= seed << 13; seed ^= seed >> 7; seed ^= seed << 17;
            let j = (seed % (i as u64 + 1)) as usize;
            v.swap(i, j);
        }
    }

    pub fn select(conn: &crate::db::Conn, col: &crate::collection::Collection,
                  today: chrono::NaiveDate, limit: Option<usize>, new_limit: Option<usize>,
                  from_deck: Option<&str>, bury: bool) -> Vec<Card> {
        let today_s = crate::timeutil::format_date(today);
        let mut due: Vec<Card> = Vec::new();
        let mut new: Vec<Card> = Vec::new();
        let mut families: HashMap<Hash, bool> = HashMap::new();
        let mut eligible: Vec<Card> = Vec::new();
        for c in &col.cards {
            if let Some(d) = from_deck { if &c.deck_name != d { continue } }
            let perf = match crate::collection::get_performance(conn, &c.hash) { Ok(p) => p, Err(_) => None };
            let is_new = perf.as_ref().map(|p| p.review_count == 0).unwrap_or(true);
            let is_due = match &perf {
                None => true,
                Some(p) => p.due_date.is_empty() || p.due_date.as_str() <= today_s.as_str(),
            };
            if !is_due { continue }
            if is_new { new.push(c.clone()); } else { due.push(c.clone()); }
            eligible.push(c.clone());
        }
        // bury siblings: keep only the lowest-hash card of each cloze family
        if bury {
            let mut best: HashMap<Hash, Card> = HashMap::new();
            let mut order: Vec<Hash> = Vec::new();
            for c in &eligible {
                if let Some(fh) = c.family_hash {
                    match best.get(&fh) {
                        Some(b) => if c.hash < b.hash { best.insert(fh, c.clone()); },
                        None => { best.insert(fh, c.clone()); order.push(fh); }
                    }
                }
            }
            eligible.retain(|c| c.family_hash.is_none() || best.get(&c.family_hash.unwrap()).map(|b| b.hash == c.hash).unwrap_or(true));
            let mut n2: Vec<Card> = Vec::new();
            let mut d2: Vec<Card> = Vec::new();
            for c in &eligible {
                if new.iter().any(|x| x.hash == c.hash) { n2.push(c.clone()) } else { d2.push(c.clone()) }
            }
            due = d2; new = n2;
        }
        shuffle(&mut due);
        shuffle(&mut new);
        let mut all: Vec<Card> = due;
        all.extend(new);
        if let Some(l) = new_limit { if all.len() > l { all.truncate(l); } }
        if let Some(l) = limit { if all.len() > l { all.truncate(l); } }
        shuffle(&mut all);
        all
    }

    pub fn is_empty(v: &[Card]) -> bool { v.is_empty() }
}

pub mod server {
    use crate::cards::{Card, CardContent, Grade};
    use std::io::{Read, Write};

    pub struct State {
        pub session: Vec<Card>,
        pub history: Vec<(Card, Grade)>,
        pub index: usize,
        pub revealed: bool,
        pub started: String,
        pub session_id: i64,
    }

    pub fn serve(conn: &crate::db::Conn, col: &crate::collection::Collection, session: Vec<Card>,
                 host: &str, port: u16, open_browser: bool, binary: bool) -> Result<(), String> {
        let addr = format!("{}:{}", host, port);
        let listener = std::net::TcpListener::bind(&addr).map_err(|e| format!("I/O error: Os {{ code: 98, kind: AddrInUse, message: \"Address already in use\" }}"))?;
        let _ = col;
        let _ = conn;
        let _ = open_browser;
        let _ = binary;
        for stream in listener.incoming() {
            let mut s = match stream { Ok(s) => s, Err(_) => continue };
            let mut buf = Vec::new();
            let mut tmp = [0u8; 4096];
            let _ = s.read(&mut tmp);
            let _ = &mut buf;
            let mut req = String::from_utf8_lossy(&tmp).into_owned();
            let _ = req;
            let body = "HTTP/1.1 200 OK\r\ncontent-type: text/html; charset=utf-8\r\n\r\nok\n";
            let _ = s.write_all(body.as_bytes());
        }
        Ok(())
    }
}
